minimo:
/* Definiciones del tema — generado desde Configuración */
:root{--cod-color-bg:#F6F6F3;--cod-color-text:#2b2926;}
body{background-color:var(--cod-color-bg);color:var(--cod-color-text);}

santaLuisa:
/* Definiciones del tema — generado desde Configuración */
:root{--cod-mode:light;color-scheme:light;--cod-color-bg:#F6F6F3;--cod-color-text:#2b2926;--cod-color-primary:#70745E;--cod-color-accent:#DDB441;--cod-font-heading:'Montserrat';--cod-font-body:'Montserrat';--cod-font-accent:'Birthstone';--cod-size-base:16px;--cod-h1-size:48px;--cod-h2-size:36px;--cod-h3-size:28px;--cod-h4-size:22px;--cod-h5-size:18px;--cod-h6-size:16px;--cod-layout-width:1200px;--cod-radius:8px;--cod-spacing:24px;--cod-landing:90px;}
:where([id]){scroll-margin-block-start:var(--cod-landing);}
body{background-color:var(--cod-color-bg);color:var(--cod-color-text);font-family:var(--cod-font-body);font-size:var(--cod-size-base);}
h1,h2,h3,h4,h5,h6{font-family:var(--cod-font-heading);}
h1{font-size:var(--cod-h1-size);}
h2{font-size:var(--cod-h2-size);}
h3{font-size:var(--cod-h3-size);}
h4{font-size:var(--cod-h4-size);}
h5{font-size:var(--cod-h5-size);}
h6{font-size:var(--cod-h6-size);}
.cod-canvas-published{max-width:var(--cod-layout-width);margin-inline:auto;}

liquido:
/* Definiciones del tema — generado desde Configuración */
:root{--cod-color-bg:#fff;--cod-layout-width:100%;}
body{background-color:var(--cod-color-bg);}

soloAterrizaje:
/* Definiciones del tema — generado desde Configuración */
:root{--cod-landing:-40px;}
:where([id]){scroll-margin-block-start:var(--cod-landing);}

soloTipografia:
/* Definiciones del tema — generado desde Configuración */
:root{--cod-font-heading:'Lora';--cod-h3-size:28px;}
h1,h2,h3,h4,h5,h6{font-family:var(--cod-font-heading);}
h3{font-size:var(--cod-h3-size);}
